export const toJSON = (schema: any) => {
  schema.set('toJSON', {
    transform: (doc: any, ret: any) => {
      ret.id = ret._id.toString();
      delete ret.__v;
      delete ret.updatedAt;
    },
  });
};

export const paginate = (schema: any) => {
  schema.statics.paginate = async function (filter: any, options: any) {
    const limit = options.limit && parseInt(options.limit, 10) > 0 ? parseInt(options.limit, 10) : 10;
    const page = options.page && parseInt(options.page, 10) > 0 ? parseInt(options.page, 10) : 1;
    const skip = (page - 1) * limit;
    const countPromise = this.countDocuments(filter).exec();
    const docsPromise = this.find(filter).sort(options.sortBy).skip(skip).limit(limit).exec();
    const [totalResults, results] = await Promise.all([countPromise, docsPromise]);
    const totalPages = Math.ceil(totalResults / limit);
    return { results, page, limit, totalPages, totalResults };
  };
};

