import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';
import * as mongoose from 'mongoose';

export type StripeErrorDocument = StripeError & Document;

@Schema({ timestamps: true, collection: 'tbl_stripe_errors', strict: false })
export class StripeError {
  @Prop({ trim: true, type: Object, default: {} })
  response_data!: Record<string, any>;

  @Prop({ type: String, trim: true })
  stripe_id!: string;

  @Prop({ type: Types.ObjectId })
  metadata_id!: Types.ObjectId;

  @Prop({ type: String, trim: true })
  operation!: string;
}

export const StripeErrorSchema = SchemaFactory.createForClass(StripeError);

// Add indexes for better query performance
StripeErrorSchema.index({ stripe_id: 1, createdAt: -1 });
StripeErrorSchema.index({ operation: 1, createdAt: -1 });

/**
 * Helper to dynamically create stripe error logs
 */
export const createStripeError = async (
  response_data: Record<string, any> = {},
  stripe_id: string | null = null,
  metadata_id: any = null,
  operation: string | null = null,
) => {
  const error: any = {
    response_data,
    stripe_id,
    metadata_id,
    operation,
  };
  try {
    const StripeErrorModel =
      mongoose.connection.models['tbl_stripe_errors'] ||
      mongoose.connection.model('tbl_stripe_errors');
    if (StripeErrorModel) {
      const keysToCheck = [
        'response_data',
        'stripe_id',
        'metadata_id',
        'operation',
      ];
      const shouldCreate = Object.keys(error).some(
        (key) => keysToCheck.includes(key) && error[key],
      );
      if (shouldCreate) {
        await StripeErrorModel.create(error);
      }
    }
  } catch (err) {
    console.error('Create Stripe Catched Error ||| ', err);
  }
};

