  @Prop({ type: Number, required: false })
  queue_priority!: number | undefined;

  @Prop({ trim: true, type: Date })
  cancelled_at!: Date;

  // @deprecated — legacy flag from pre-queue redesign; replaced by status enum (active/future/expired/cancelled).
  // New flow never sets this; safe to remove after confirming zero true rows in production (db.tbl_sellers.find({'subscriptions.is_plan_cancel': true}).count()).
  @Prop({ trim: true, type: Boolean, default: false })
  is_plan_cancel!: boolean;

  @Prop({ trim: true, type: Date, default: Date.now })
