  plan_price!: number;

  @Prop({ trim: true, type: String, uppercase: true })
  currency_code!: string;

  @Prop({ trim: true, enum: ['month', 'quarterly', 'both'], type: String })
  plan_interval!: string;

  @Prop({ trim: true, type: Number, default: 0 })
  trial_days!: number;

  @Prop({
    type: [
      {
        _id: false,
        feature_id: { type: Types.ObjectId },
        usage_count: { type: Number },
        feature_name: { type: String, default: '' },
      },
    ],
    default: [],
  })
  features!: {
