// ── Main seller schema ────────────────────────────────────────────────────────
@Schema({ timestamps: true, collection: 'tbl_sellers' })
export class User {
  // ── Identity ─────────────────────────────────────────────────────────
  @Prop({ type: String, required: true, trim: true })
  first_name!: string;

  @Prop({ type: String, required: true, trim: true })
  last_name!: string;

  @Prop({
    type: String,
    required: true,
    trim: true,
    lowercase: true,
    validate(value: string) {
      if (!validator.isEmail(value)) throw new Error('Invalid email');
    },
  })
  email!: string;

  @Prop({ trim: true, type: String, minlength: 10 })
  contact_no!: string;

  @Prop({ type: String, trim: true })
  company_name!: string;

  // ── Checkout business info (copied from tbl_guest_leads on payment success) ──
  @Prop({ type: String, trim: true })
  country_name!: string;

  @Prop({ type: String, trim: true })
  business_address!: string;

  @Prop({ type: Types.ObjectId, ref: 'tbl_portals' })
  portal_id!: Types.ObjectId;

  @Prop({ trim: true, type: String })
  avatar!: string;

  @Prop({ trim: true, type: String })
  profileImgUrl!: string;

  // ── Role & flags ─────────────────────────────────────────────────────
  @Prop({ type: Types.ObjectId, required: false, default: null })
  role!: Types.ObjectId | null;

  @Prop({ trim: true, type: Boolean, default: false })
  isSuperAdmin!: boolean;

  @Prop({ trim: true, type: Boolean, default: false })
  isPremisesUser!: boolean;

  @Prop({ trim: true, type: Boolean, default: false })
  isDeveloper!: boolean;

  @Prop({ type: Types.ObjectId, ref: 'tbl_sellers' })
  seller_id!: Types.ObjectId;

  @Prop({ trim: true, type: Boolean, default: false })
  is_seller_user!: boolean;

  // ── Auth ─────────────────────────────────────────────────────────────
  @Prop({ trim: true, type: Boolean, default: false })
  isEmailVerified!: boolean;

  @Prop({ trim: true, type: Number, default: 1 })
  status!: number; // 0=Inactive, 1=Active, 2=Deleted

  // ── Email tracking ────────────────────────────────────────────────────
  @Prop({ trim: true, type: Boolean, default: false })
  welcome_email_sent!: boolean;

  // ── Subscriptions (replaces tbl_user_plans entirely) ─────────────────
  @Prop({ trim: true, type: [SubscriptionSchema], default: [] })
  subscriptions!: Subscription[];
}

export const UserSchema = SchemaFactory.createForClass(User);

// ── Indexes ───────────────────────────────────────────────────────────────────
UserSchema.index({ email: 1 }, { unique: true });
UserSchema.index({ 'subscriptions.expired_at': 1 });
UserSchema.index({ 'subscriptions.status': 1 });

UserSchema.plugin(toJSON);
UserSchema.plugin(paginate);

UserSchema.statics.isEmailTaken = async function (
  email: string,
  excludeUserId?: Types.ObjectId,
) {
  const user = await this.findOne({ email, _id: { $ne: excludeUserId } });
  return !!user;
};

UserSchema.pre('save', async function () {
  const user = this as any;
  const first = String(user.first_name ?? '').trim();
  const last = String(user.last_name ?? '').trim();
  if (!first && !last) return;
  user.profileImgUrl = `https://avatar.oxro.io/avatar.svg?name=${first.toUpperCase()}+${last.toUpperCase()}&background=084f08`;
});

UserSchema.pre('findOneAndUpdate', async function () {
  const update = this.getUpdate() as any;
  if (update?.first_name && update?.last_name) {
    await this.updateOne(
      {},
      {
        $set: {
          profileImgUrl: `https://avatar.oxro.io/avatar.svg?name=${update.first_name.toUpperCase()}+${update.last_name.toUpperCase()}&background=084f08`,
        },
      },
    );
  }
});

