UserSchema.statics.isEmailTaken = async function (
  email: string,
  excludeUserId?: Types.ObjectId,
) {
  const user = await this.findOne({ email, _id: { $ne: excludeUserId } });
  return !!user;
};

UserSchema.pre('save', async function () {
  const user = this as any;
  const first = String(user.first_name ?? '').trim();
  const last = String(user.last_name ?? '').trim();
  if (!first && !last) return;
  user.profileImgUrl = `https://avatar.oxro.io/avatar.svg?name=${first.toUpperCase()}+${last.toUpperCase()}&background=084f08`;
});

UserSchema.pre('findOneAndUpdate', async function () {
  const update = this.getUpdate() as any;
  if (update?.first_name && update?.last_name) {
    await this.updateOne(
      {},
      {
        $set: {
          profileImgUrl: `https://avatar.oxro.io/avatar.svg?name=${update.first_name.toUpperCase()}+${update.last_name.toUpperCase()}&background=084f08`,
        },
      },
    );
  }
});

