import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';

export type MetaBlobVersionDocument = MetaBlobVersion & Document;

export type ProductBlobKind = 'amz_white_label' | 'amz_wl_update_attrs';

@Schema({ timestamps: true, collection: 'tbl_meta_blob_versions' })
export class MetaBlobVersion {
  @Prop({ type: Types.ObjectId, required: true, index: true })
  owner_doc_id!: Types.ObjectId;

  @Prop({
    type: String,
    required: true,
    enum: ['amz_white_label', 'amz_wl_update_attrs'],
  })
  kind!: ProductBlobKind;

  @Prop({ type: Number, required: true })
  version_no!: number;

  @Prop({ type: String, required: true })
  sha256!: string;

  @Prop({ type: Types.ObjectId, sparse: true })
  seller_id?: Types.ObjectId;

  @Prop({ type: String })
  marketplace_id?: string;

  @Prop({ type: Boolean, default: false })
  is_head!: boolean;

  /** full = v1 baseline; delta = JSON patch vs v1 */
  @Prop({ type: String, default: 'full', enum: ['full', 'delta'] })
  storage_mode!: 'full' | 'delta';

  @Prop({ type: Number })
  baseline_version_no?: number;

  /** Canonical SHA256 of materialized JSON (change detection). */
  @Prop({ type: String })
  content_hash?: string;

  /** gzip patch bytes hash (delta versions). */
  @Prop({ type: String })
  patch_sha256?: string;

  @Prop({ type: Number })
  patch_stored_size?: number;
}

export const MetaBlobVersionSchema =
  SchemaFactory.createForClass(MetaBlobVersion);

MetaBlobVersionSchema.index({ owner_doc_id: 1, kind: 1, version_no: -1 });
MetaBlobVersionSchema.index(
  { owner_doc_id: 1, kind: 1, is_head: 1 },
  { partialFilterExpression: { is_head: true } },
);
MetaBlobVersionSchema.index({ sha256: 1 });
MetaBlobVersionSchema.index({ seller_id: 1, createdAt: -1 });

