import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document } from 'mongoose';

export type ChatbotCacheDocument = ChatbotCache & Document;

@Schema({ collection: 'chatbot_cache', timestamps: true })
export class ChatbotCache {
  // Lowercased / whitespace-collapsed version of originalQuestion, used as
  // the lookup key so near-duplicate phrasing still hits the cache.
  @Prop({ type: String, trim: true, required: true, unique: true, index: true })
  normalizedQuestion: string;

  @Prop({ type: String, trim: true, required: true })
  originalQuestion: string;

  @Prop({ type: String, trim: true, required: true })
  answer: string;

  // Which pipeline stage produced this answer ('faq' | 'pricing' |
  // 'knowledge' | 'ai'), so a cache hit can still show the right badge.
  @Prop({ type: String, trim: true, default: '' })
  source: string;

  @Prop({ type: Number, default: 0 })
  hits: number;

  // Auto-generated answers are served immediately for speed. `approved`
  // is reserved for a future admin review flow that can override them.
  @Prop({ type: Boolean, default: false })
  approved: boolean;
}

export const ChatbotCacheSchema = SchemaFactory.createForClass(ChatbotCache);

import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';

export type FaqDocument = Faq & Document;

/**
 * tbl_faqs — collection for Frequently Asked Questions (Support FAQ).
 * Status: 1 = Active, 0 = Inactive, 2 = Deleted (Soft Delete).
 */
@Schema({ timestamps: true, collection: 'tbl_faqs' })
export class Faq {
  /** The FAQ question text */
  @Prop({ type: String, required: true, trim: true })
  question!: string;

  /** Detailed answer content */
  @Prop({ type: String, required: true, trim: true })
  answer!: string;

  /** Category grouping matching seller support ticket categories */
  @Prop({ type: String, required: true, trim: true })
  category!: string;

  /** Status flag: 1 = Active, 0 = Inactive, 2 = Soft Deleted */
  @Prop({ type: Number, default: 1, enum: [0, 1, 2] })
  status!: number;

  /** User (Admin) who created the FAQ */
  @Prop({ type: Types.ObjectId, ref: 'User' })
  createdBy?: Types.ObjectId;

  /** User (Admin) who last updated the FAQ */
  @Prop({ type: Types.ObjectId, ref: 'User' })
  updatedBy?: Types.ObjectId;
}

export const FaqSchema = SchemaFactory.createForClass(Faq);

// Indexing for search performance & default sorting (latest created first)
FaqSchema.index({ category: 1, createdAt: -1, status: 1 });
FaqSchema.index({ question: 'text', answer: 'text' });

