import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';
import { toJSON } from '../../common/plugins/to-json.plugin';
import { paginate } from '../../common/plugins/paginate.plugin';
import { Schema as MongooseSchema } from 'mongoose';

export type PaymentDocument = Payment & Document;

export enum PaymentStatus {
  CREATED = 'created',
  PENDING = 'pending',
  SUCCESS = 'success',
  FAILED = 'failed',
  CANCELLED = 'cancelled',
  REFUNDED = 'refunded',
}

/**
 * tbl_payments — immutable financial ledger.
 * One record per payment attempt. Never deleted.
 * user_id populated after seller account creation.
 */
@Schema({ timestamps: true, collection: 'tbl_payments' })
export class Payment {
  @Prop({ type: Types.ObjectId, required: true })
  lead_id!: Types.ObjectId;

  /** Populated after seller account creation via _createSellerAccount() */
  @Prop({ type: Types.ObjectId, ref: 'User', default: null })
  user_id!: Types.ObjectId;

  @Prop({ type: Types.ObjectId, ref: 'Plan', required: true })
  plan_id!: Types.ObjectId;

  /** Smallest unit — paise (INR) or cents (USD) */
  @Prop({ trim: true, type: Number, required: true })
  amount!: number;

  /** Uppercase e.g. "INR", "USD" */
  @Prop({ trim: true, type: String, required: true, uppercase: true })
  currency_code!: string;

  @Prop({
    trim: true,
    type: String,
    required: true,
    enum: ['monthly', 'quarterly'],
  })
  billing_cycle!: string;

  /** Gateway selected by user on payment step. 'manual' = admin-managed offline payment. */
  @Prop({
    trim: true,
    type: String,
    required: true,
    enum: ['stripe', 'razorpay', 'manual'],
  })
  gateway!: string;

  /** Razorpay order_id | Stripe session id */
  @Prop({ trim: true, type: String })
  order_id!: string;

  /** Razorpay payment_id | Stripe payment_intent id */
  @Prop({ trim: true, type: String })
  transaction_id!: string;

  /** Razorpay HMAC signature */
  @Prop({ trim: true, type: String })
  signature!: string;

  @Prop({
    trim: true,
    type: String,
    default: PaymentStatus.CREATED,
    enum: Object.values(PaymentStatus),
  })
  status!: string;

  @Prop({ trim: true, type: MongooseSchema.Types.Mixed, default: {} })
  gateway_response!: Record<string, any>;

  @Prop({ trim: true, type: Date })
  paid_at!: Date;
}

export const PaymentSchema = SchemaFactory.createForClass(Payment);
PaymentSchema.index({ lead_id: 1, gateway: 1, status: 1 });
PaymentSchema.index({ order_id: 1 });
PaymentSchema.index({ transaction_id: 1 });
PaymentSchema.index({ user_id: 1 });
PaymentSchema.plugin(toJSON);
PaymentSchema.plugin(paginate);

