import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { Document, Types } from 'mongoose';
import { toJSON } from '../../../common/plugins/to-json.plugin';
import { paginate } from '../../../common/plugins/paginate.plugin';
import { TICKET_STATUS } from '../../../common/constants/support-ticket.constants';

export type SupportTicketDocument = SupportTicket & Document;

// ── Attachment sub-document ───────────────────────────────────────────────────
@Schema({ _id: false })
export class TicketAttachment {
  @Prop({ type: String, trim: true, required: true })
  url!: string;

  @Prop({ type: String, trim: true })
  fileName!: string;

  @Prop({ type: String, trim: true })
  mimeType!: string;

  @Prop({ type: Number })
  size!: number;
}

export const TicketAttachmentSchema =
  SchemaFactory.createForClass(TicketAttachment);

// ── Message sub-document (embedded — NO separate collection) ──────────────────
@Schema({ _id: true })
export class TicketMessage {
  /** Who sent this message — ObjectId ref to tbl_sellers */
  @Prop({ type: Types.ObjectId, ref: 'User', required: true })
  senderId!: Types.ObjectId;

  /** Display name of the sender at the time of message */
  @Prop({ type: String, trim: true })
  senderName?: string;

  /**
   * Sender role string: 'seller' | 'seller_user' | 'admin' | 'support'
   * Stored as plain string (no enum) per project convention.
   */
  @Prop({ type: String, trim: true, required: true })
  senderRole!: string;

  /** Message body text */
  @Prop({ type: String, trim: true, required: true })
  message!: string;

  /** File attachments associated with this message */
  @Prop({ type: [TicketAttachmentSchema] })
  attachments!: TicketAttachment[];

  /**
   * Internal note — visible only to admin/support staff, hidden from seller/seller_user.
   * Default: false (customer-visible reply).
   */
  @Prop({ type: Boolean, default: false })
  isInternal!: boolean;

  /** Whether the opposite party has read this message */
  @Prop({ type: Boolean, default: false })
  isRead!: boolean;

  @Prop({ type: Date })
  readAt!: Date | null;

  /** Explicit createdAt on sub-document (timestamps not auto-set on embedded docs) */
  @Prop({ type: Date, default: () => new Date() })
  createdAt!: Date;
}

export const TicketMessageSchema = SchemaFactory.createForClass(TicketMessage);

// ── Main ticket document ──────────────────────────────────────────────────────
/**
 * tbl_support_tickets — single collection for both tickets AND their messages.
 * Messages are embedded as an array within the ticket document.
 * Status is stored as a Number (1–7) per constants/support-ticket.constants.ts.
 * Category is a plain String — no enum.
 */
@Schema({ timestamps: true, collection: 'tbl_support_tickets' })
export class SupportTicket {
  /** Auto-generated sequential ticket code, e.g. TCK-000031 */
  @Prop({ type: String, trim: true, unique: true })
  ticketNo!: string;

  /** Parent seller's _id (tbl_sellers). Always set — even for seller_user created tickets. */
  @Prop({ type: Types.ObjectId, ref: 'User', required: true })
  sellerId!: Types.ObjectId;

  /**
   * The seller user who created this ticket.
   * null when the ticket was created directly by the Seller.
   */
  @Prop({ type: Types.ObjectId, ref: 'User' })
  sellerUserId!: Types.ObjectId | null;

  /** Actual creator: either the seller _id or the seller_user _id */
  @Prop({ type: Types.ObjectId, ref: 'User', required: true })
  createdBy!: Types.ObjectId;

  @Prop({ type: String, trim: true, required: true })
  subject!: string;

  /** Free-form category string (no enum) — e.g. "Orders", "Inventory", "Technical" */
  @Prop({ type: String, trim: true })
  category!: string;

  /**
   * Ticket status stored as Number:
   * 1=Open, 2=Assigned, 3=Pending Customer, 4=Pending Support,
   * 5=Resolved, 6=Closed, 7=Reopened
   */
  @Prop({ type: Number, default: TICKET_STATUS.OPEN })
  status!: number;

  /** Admin/support user assigned to handle this ticket */
  @Prop({ type: Types.ObjectId, ref: 'User' })
  assignedToUserId!: Types.ObjectId | null;

  /** Preview text of the most recent message (for list view) */
  @Prop({ type: String, trim: true })
  lastMessage!: string;

  @Prop({ type: Date })
  lastMessageAt!: Date | null;

  /** Unread message count for the seller/seller_user side */
  @Prop({ type: Number })
  unreadSellerCount!: number;

  /** Unread message count for the admin/support side */
  @Prop({ type: Number })
  unreadAdminCount!: number;

  /**
   * Embedded message thread — no separate tbl_support_ticket_messages collection.
   * Each push adds a new message object with its own _id.
   */
  @Prop({ type: [TicketMessageSchema] })
  messages!: TicketMessage[];
}

export const SupportTicketSchema = SchemaFactory.createForClass(SupportTicket);

// ── Indexes ───────────────────────────────────────────────────────────────────
SupportTicketSchema.index({ sellerId: 1 });
SupportTicketSchema.index({ sellerUserId: 1 });
SupportTicketSchema.index({ createdBy: 1 });
SupportTicketSchema.index({ status: 1 });
SupportTicketSchema.index({ assignedToUserId: 1 });
SupportTicketSchema.index({ lastMessageAt: -1 });

SupportTicketSchema.plugin(toJSON);
SupportTicketSchema.plugin(paginate);

